// Normalize and validate the incoming booking request.
const body = $input.first().json.body ?? $input.first().json;

const name = (body.name || '').toString().trim();
const email = (body.email || '').toString().trim();
const phone = body.phone ? body.phone.toString().trim() : '';
const date = (body.date || '').toString().trim();
const people = parseInt(body.people, 10) || 1;
const message = body.message ? body.message.toString().trim() : '';
const lang = ['en', 'fr', 'es'].includes(body.lang) ? body.lang : 'en';
const tour = body.tour || {};
const tourName = tour[lang] || tour.en || 'a tour';
const price = body.price || '';
const pageUrl = body.pageUrl || '';

if (!name || !email || !date) {
  throw new Error('Missing required field: name, email, and date are all required.');
}

return [{
  json: { name, email, phone, date, people, message, lang, tourName, price, pageUrl }
}];

// Build the language-specific text used by every downstream node.
const d = $input.first().json;

const telegramText = `New booking request!

Tour: ${d.tourName}
Date: ${d.date}
People: ${d.people}
Price: ${d.price || 'n/a'}

Name: ${d.name}
Email: ${d.email}
Phone: ${d.phone || 'not given'}
${d.message ? 'Message: ' + d.message : ''}

From: ${d.pageUrl}`;

const guestSubject = {
  en: `Your request for ${d.tourName} — Savor & Stories`,
  fr: `Votre demande pour ${d.tourName} — Savor & Stories`,
  es: `Tu solicitud para ${d.tourName} — Savor & Stories`,
}[d.lang];

const guestBody = {
  en: `Hi ${d.name},

Thanks for your request for "${d.tourName}" on ${d.date} for ${d.people} people.

This is not a confirmed booking yet — Antoine confirms every booking personally and will get back to you by email or WhatsApp shortly to lock in the details.

If anything is urgent, message him directly on WhatsApp: https://wa.me/33626391783

À bientôt,
Savor & Stories`,
  fr: `Bonjour ${d.name},

Merci pour votre demande pour "${d.tourName}" le ${d.date} pour ${d.people} personnes.

Ce n'est pas encore une réservation confirmée — Antoine confirme chaque réservation personnellement et reviendra vers vous par e-mail ou WhatsApp très bientôt pour finaliser les détails.

Pour toute urgence, écrivez-lui directement sur WhatsApp : https://wa.me/33626391783

À bientôt,
Savor & Stories`,
  es: `Hola ${d.name},

Gracias por tu solicitud para "${d.tourName}" el ${d.date} para ${d.people} personas.

Esto todavía no es una reserva confirmada — Antoine confirma cada reserva personalmente y te contactará por correo o WhatsApp muy pronto para concretar los detalles.

Si es urgente, escríbele directamente por WhatsApp: https://wa.me/33626391783

Hasta pronto,
Savor & Stories`,
}[d.lang];

const calendarSummary = `PENDING: ${d.tourName} — ${d.name} (${d.people}p)`;
const calendarDescription = `Booking request via website, not yet confirmed.

Name: ${d.name}
Email: ${d.email}
Phone: ${d.phone || 'not given'}
People: ${d.people}
Language: ${d.lang}
${d.message ? 'Message: ' + d.message : ''}`;

return [{
  json: {
    ...d,
    telegramText,
    guestSubject,
    guestBody,
    calendarSummary,
    calendarDescription,
  }
}];
